  /**
   * Submit an egress-health run
   *
   * Store one egress-health run: over the provider's tunnel, how many of
   * the sampled loads of each class passed after their retries -- a load
   * fails only when every attempt failed (connect/GEOMAP.md §11.3). Loads
   * whose tunnel could not be re-created, and canaries, are in no count
   * and are named apart. A failed load of a site on probation, or of one
   * marked incompatible with the provider's place, is taken out of the
   * counts by the server and named in the stored row's
   * `unscored_failed_names`. The row is an upsert keyed on client_id, so a bad submission
   * does not sit beside the good one -- it destroys the last good
   * measurement. Everything is therefore validated before anything is
   * stored, and unknown fields are rejected outright (a misspelled field
   * would decode to a perfectly consistent zero, filling the table with
   * plausible rows describing a measurement that never happened).
   *
   * `class_results` must sum EXACTLY to `ok_count`/`total_count`: the
   * classes are the score, and a total that does not decompose into them
   * means the two halves came from different runs. The reputation class
   * dissolved into the sites: `reputation_ok`, `reputation_total` and
   * `reputation_failed_names` are accepted, always zero from a current
   * prober, and ignored, and a `reputation` key inside `class_results` is
   * still refused.
   *
   * `POST /network/provider-egress-health` — operationId `Provider Egress Health Result`, auth: operator
   */
  providerEgressHealthResult(body: T.SubmitProviderEgressHealthArgs, options?: RequestOptions): Promise<T.SubmitProviderEgressHealthResult> {
    return this.call<T.SubmitProviderEgressHealthResult>(
      { id: "Provider Egress Health Result", method: "POST", path: "/network/provider-egress-health", auth: "operator", body: "json", response: "json" },
      undefined,
      body,
      options,
    );
  }

